# Builds facts/facts.md: every spoken number (and every number on a card) -> the log file:line it is read from.
# usage: python3 make_facts.py <take dir>   (the take's film.log is copied into facts/ as film_take.log first). Refuses when a pattern is not found.
import sys, os, re, shutil
W = os.path.dirname(os.path.abspath(__file__)); F = os.path.join(W, 'facts'); take = sys.argv[1]
shutil.copy(os.path.join(W, take, 'film.log'), os.path.join(F, 'film_take.log'))
def where(fn, pat):
    for i, l in enumerate(open(os.path.join(F, fn), encoding='utf8', errors='replace'), 1):
        if re.search(pat, l): return f'{fn}:{i}', l.strip()[:230]
    sys.exit(f'MISSING {fn} /{pat}/')
ROWS = [
 ('d01', 'two storeys', 'witness_dxf_convert_std.log', r'PASS C2 IFC'),
 ('d01', 'one hundred and ninety-six elements', 'film_take.log', r'duplex.seed=.*elements=196'),
 ('s01', 'eight sheets: two floor plans, four elevations, a roof plan, a section', 'std2d_run.log', r'^FLOOR_GF:'),
 ('s01', 'the same on every run (two runs; five processes)', 'test_std2d.log', r'PASS W1-proc \|'),
 ('s02', 'grid on the load-bearing wall axes', 'test_std2d.log', r'PASS W2 \|'),
 ('s02', 'one to three, A to D', 'test_std2d.log', r'PASS W4 \|'),
 ('s02', 'thirty-four dimensions, each equal to the model, no overrides', 'test_std2d.log', r'PASS W3\[DX_FLOOR_GF_std.dxf\]'),
 ('s03', 'fourteen doors, fourteen arcs, hinge and swing from the IFC', 'test_std2d.log', r'PASS W5 \|'),
 ('s03', 'old hand-made set: swing side six in fourteen', 'test_std2d.log', r'^INFO earlier timestamped set'),
 ('s02/s03 badges', '34 DIMENSION entities; 8 of 14 door arcs on the FF sheet; grid 1-3, A-D', 'render_sheets.log', r'FLOOR_FF .*door_arcs=8'),
 ('i01', 'all eight sheets at once (chooser, multiple)', 'film_take.log', r'chooser=row=Open 2D drawings .* files=8'),
 ('i02', 'each sheet placed at floor / face / roof / cut', 'witness_dxf_convert_std.log', r'PASS C0 CANVAS std'),
 ('e01', 'every value shows its source: from model', 'film_take.log', r'editor.B=.*from model'),
 ('e02', 'qualifies; zero blocking, seventy-five pieces of advice (page)', 'film_take.log', r'verdict.B=.*"nB":0,"nA":75'),
 ('e02', 'same verdict, Node run', 'rosetta_qualify.log', r'^verdict=qualifies blocking=0 advisory=75'),
 ('v01', 'one gesture, one hundred and seventy-one operations', 'film_take.log', r'convert=op-log 0->171'),
 ('v01', 'every element within a millimetre of the reference run', 'witness_dxf_convert_std.log', r'PASS C1 PARITY'),
 ('v02', 'ninety-six wall pieces, two slabs, a roof, fourteen doors, twenty-two windows; two storeys', 'witness_dxf_convert_std.log', r'PASS C2 IFC'),
 ('r01', 'the same eight sheets, marking layer removed, byte for byte what the writer drew', 'film_take.log', r'raw.bytes=.*ALL 8'),
 ('r01', 'no role, no units, Convert off', 'film_take.log', r'raw.red=.*"convertDisabled":true'),
 ('r02', 'view picked, suggestions ticked, level typed (GF, live)', 'film_take.log', r'FILL live GF'),
 ('r03', 'seventy-five suggestions ticked, twenty-nine values picked or typed (all eight sheets)', 'film_take.log', r'fill.total=ticks=75 picked_or_typed=29'),
 ('r04', 'fourteen doors have no height (blocked 28 = 14 no_elevation_height + 14 no_host_cut)', 'film_take.log', r'raw.after=.*"GAP:no_elevation_height":14'),
 ('r04', 'Convert stays off', 'film_take.log', r'raw.convert=disabled=true'),
 ('o02', 'header says millimetres; 0.80 x 0.56 m; radius 24 to 36 (24, 28, 30, 36); 20.2 x 14.3 m', 'jscad_units_probe.log', r'INSUNITS=4'),
 ('o02', 'units carry their source (units_source=config)', 't8_sandbox_jscad.log', r'units_source=config'),
 ('l01', 'the door and window library is local', 'witness_dxf_import_node_std.log', r'LIB-SUBSET wrote'),
 ('l01 card', 'Farmhouse partial: qualify blocked (49)', 'rosetta_qualify.log', r'^verdict=blocked blocking=49'),
 ('l01', 'thirty-nine wall bases from the plan level, advice (15, Level 1)', 'rosetta_dx_shell_std.log', r'Level 1 L2.8: wall bases'),
 ('l01', 'thirty-nine wall bases from the plan level, advice (24, Level 2)', 'rosetta_dx_shell_std.log', r'Level 2 L2.8: wall bases'),
 ('l01', 'thirty-nine = walls advisory in the std verdict', 'rosetta_qualify.log', r'"walls":\{"verdict":"qualifies","blocking":0,"advisory":39\}'),
 ('l01', 'old hand-made set: roof forty-three millimetres high (6.5 vs 6.457)', 'rosetta_dx_shell_old.log', r'FAIL RF-d'),
]
out = ['# DXF2BIM English film: facts mapping (generated by make_facts.py from the logs in this folder; take = ' + take + ')', '',
       'Every number the voices say or a card shows, the log line it is read from. Logs were produced fresh on 2026-10-16 (BIMCompiler master be1dcda91',
       'worktree, bim-ootb feat/dxf2bim-editor 5e659fd5 worktree, DXF2BIM_BC set). Text-only sources (not logs) are listed at the end.', '',
       '| beat | spoken / shown | file:line | line |', '|---|---|---|---|']
for b, what, fn, pat in ROWS:
    loc, line = where(fn, pat); out.append(f'| {b} | {what} | `{loc}` | `{line.replace("|", "/")}` |')
out += ['', 'Text sources (no number from a run):',
 '- o01 prior art: BIMCompiler `docs/DXF2BIM_SPEC.md` l.14 (Revit/ArchiCAD manual trace), l.16 (CrossBIM: structural only, layer names typed), l.17 (IfcOpenShell #1950: curves only), l.18 (co2tools: DXF->STL extrude per part), l.20 (claim wording: "no general, deterministic FOSS DXF->BIM tool found").',
 '- o02 settled by evidence: `docs/DXF2BIM_SPEC.md` l.211.',
 '- o03 rules a real drawing taught: `docs/DXF2BIM_SPEC.md` l.450 (T-joint: join across gaps up to one wall thickness), l.451 (porch decking: 2 exclusion zones).',
 '- r04 / n01 no door schedule in the editor: bim-ootb `modeller/dxf_meta_editor.js` `vocab()` (schedule read from @SCHEDULE markings only; no UI path adds one); measured in Node: std set minus @SCHEDULE -> blocked 28 (same 14 + 14).',
 '- l01 library local: bim-ootb `prompts/DXF2BIM_MODELLER_LANE.md` §L3.2 (subset written to a git-ignored dir; deploy open). Farmhouse partial: the local film plan §4b (not in repo).',
 '- n01 credit: `tests/dxf2bim/external/farmhouse/ATTRIBUTION.txt` ("American Farmhouse" CAD files by Jay Osborne, freefarmhouse.com, CC BY-SA). MIT: bim-ootb LICENSE.',
]
open(os.path.join(F, 'facts.md'), 'w').write('\n'.join(out) + '\n'); print('wrote', os.path.join(F, 'facts.md'), len(ROWS), 'rows')
